1	/**
2	 * Тесты объёмного веса: формула (д×ш×в)/5 в граммах и округление вверх до 100 г.
3	 */
4	
5	import { strictEqual } from 'node:assert/strict';
6	import { describe, it } from 'node:test';
7	
8	import { FRAGILITY_FACTOR, volumetricWeightG } from '../src/index.ts';
9	
10	describe('объёмный вес', () => {
11	  it('ровная ячейка: 20×25×10 = 5000 см³ → 1000 г', () => {
12	    strictEqual(volumetricWeightG([20, 25, 10]), 1000);
13	  });
14	
15	  it('округление вверх до 100 г: 15×15×10 = 2250 см³ → 450 г → 500', () => {
16	    strictEqual(volumetricWeightG([15, 15, 10]), 500);
17	  });
18	
19	  it('порядок сторон не важен', () => {
20	    strictEqual(volumetricWeightG([10, 15, 15]), volumetricWeightG([15, 15, 10]));
21	  });
22	
23	  it('коэффициент хрупкости зафиксирован', () => {
24	    strictEqual(FRAGILITY_FACTOR, 1.5);
25	  });
26	});
27

{
  "q1": [
    "Коэффициент упаковки — 1.2, применяется к объёмному весу ПОСЛЕ формулы (д×ш×в)/5, до округления; итог округляется вверх до 100 г, как и раньше."
  ]
}
